/**
 * Test case: discriminator-aware inline union flattening
 *
 * Unlike the "discriminator-field-intersection-flattening" test where the union
 * (`ActionPart`) is exported as a top-level type, here the union exists only as
 * an inline field type within `Container.parts`. The union type name
 * (`ContainerPart`) is auto-generated by gqlkit and never appears in source.
 *
 * This tests the `flattenInlineUnionMembers()` code path in the auto-type
 * generator pipeline, which handles discriminator-aware flattening for inline
 * unions discovered during type extraction.
 */

type BaseInvocation = { callId: string; title: string | null };
type InvocationStates =
  | { state: "pending"; input: string; output?: never }
  | { state: "running"; input: string; output?: never }
  | { state: "done"; input: string; output: string }
  | {
      state: "error";
      input: string | undefined;
      output?: never;
      errorText: string;
    };

// The union is NOT exported — it only appears as the element type of `parts`.
// gqlkit auto-generates the union name as "ContainerPart".
export type Container = {
  parts: (
    | { type: "text"; content: string }
    | ({ type: "tool-a" } & BaseInvocation & InvocationStates)
    | ({ type: "tool-b" } & BaseInvocation & InvocationStates)
  )[];
};
